#!/usr/bin/env bash
# Publish this repo's rules and skills into user-level agent config folders.
# Additive: existing non-link files/dirs are left untouched; our own links and
# generated files are refreshed. Safe to re-run anytime (e.g. after `git pull`).
set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
SRC="$REPO_ROOT/.claude"
CLAUDE_DEST="$HOME/.claude"
COPILOT_SKILLS_DEST="$HOME/.copilot/skills"
GENERATED_MARKER="Generated by ChekTek/ai scripts/update-config"

if [ -n "${COPILOT_USER_PROMPTS_DIR:-}" ]; then
  COPILOT_PROMPTS_DEST="$COPILOT_USER_PROMPTS_DIR"
elif [ -n "${VSCODE_USER_PROMPTS_FOLDER:-}" ]; then
  COPILOT_PROMPTS_DEST="$VSCODE_USER_PROMPTS_FOLDER"
elif [ "$(uname -s)" = "Darwin" ]; then
  COPILOT_PROMPTS_DEST="$HOME/Library/Application Support/Code/User/prompts"
else
  COPILOT_PROMPTS_DEST="$HOME/.config/Code/User/prompts"
fi

link_kind() {
  dest="$1"
  label="$2"
  kind="$3"
  mkdir -p "$dest/$kind"
  for item in "$SRC/$kind"/*; do
    [ -e "$item" ] || continue # skip if the glob matched nothing
    name="$(basename "$item")"
    target="$dest/$kind/$name"
    if [ -L "$target" ]; then
      ln -sfn "$item" "$target"
      echo "updated: $label/$kind/$name"
    elif [ -e "$target" ]; then
      echo "skip existing: $label/$kind/$name"
    else
      ln -s "$item" "$target"
      echo "linked: $label/$kind/$name"
    fi
  done
}

can_write_generated_file() {
  target="$1"
  [ ! -e "$target" ] || grep -q "$GENERATED_MARKER" "$target"
}

generate_instruction() {
  source="$1"
  relative="${source#$SRC/rules/}"
  name="${relative%.md}"
  name="${name//\//-}"
  target="$COPILOT_PROMPTS_DEST/$name.instructions.md"

  if ! can_write_generated_file "$target"; then
    echo "skip existing: copilot instructions/$name.instructions.md"
    return
  fi

  mkdir -p "$COPILOT_PROMPTS_DEST"
  tmp="$(mktemp)"
  awk -v name="$name" -v marker="$GENERATED_MARKER from .claude/rules/$relative" '
    NR == 1 && $0 == "---" { in_frontmatter = 1; next }
    in_frontmatter && $0 == "---" {
      print "---"
      for (i = 1; i <= description_count; i++) print descriptions[i]
      printf "name: \"%s\"\n", name
      if (path_count == 1) {
        print "applyTo: " paths[1]
      } else if (path_count > 1) {
        print "applyTo:"
        for (i = 1; i <= path_count; i++) print "    - " paths[i]
      }
      print "---"
      print "<!-- " marker " -->"
      print ""
      in_frontmatter = 0
      next
    }
    in_frontmatter {
      if ($0 ~ /^description:/) {
        descriptions[++description_count] = $0
        in_paths = 0
        next
      }
      if ($0 ~ /^paths:[[:space:]]*$/) {
        in_paths = 1
        next
      }
      if (in_paths && $0 ~ /^[[:space:]]*-[[:space:]]*/) {
        line = $0
        sub(/^[[:space:]]*-[[:space:]]*/, "", line)
        paths[++path_count] = line
        next
      }
      in_paths = 0
      next
    }
    { print }
  ' "$source" > "$tmp"
  mv "$tmp" "$target"
  echo "generated: copilot instructions/$name.instructions.md"
}

generate_prompt() {
  skill_dir="$1"
  source="$skill_dir/SKILL.md"
  [ -f "$source" ] || return

  name="$(basename "$skill_dir")"
  target="$COPILOT_PROMPTS_DEST/$name.prompt.md"

  if ! can_write_generated_file "$target"; then
    echo "skip existing: copilot prompts/$name.prompt.md"
    return
  fi

  mkdir -p "$COPILOT_PROMPTS_DEST"
  tmp="$(mktemp)"
  awk -v fallback_name="$name" -v marker="$GENERATED_MARKER from .claude/skills/$name/SKILL.md" '
    NR == 1 && $0 == "---" { in_frontmatter = 1; next }
    in_frontmatter && $0 == "---" {
      print "---"
      if (!has_name) printf "name: %s\n", fallback_name
      for (i = 1; i <= field_count; i++) print fields[i]
      print "---"
      print "<!-- " marker " -->"
      print ""
      in_frontmatter = 0
      next
    }
    in_frontmatter {
      if ($0 ~ /^name:/) has_name = 1
      if ($0 ~ /^(name|description|argument-hint|agent|model|tools):/) fields[++field_count] = $0
      next
    }
    { print }
  ' "$source" > "$tmp"
  mv "$tmp" "$target"
  echo "generated: copilot prompts/$name.prompt.md"
}

generate_copilot_instructions() {
  find "$SRC/rules" -type f -name '*.md' -print0 | while IFS= read -r -d '' rule; do
    generate_instruction "$rule"
  done
}

generate_copilot_prompts() {
  kind="$1"
  for skill_dir in "$SRC/$kind"/*; do
    [ -d "$skill_dir" ] || continue
    generate_prompt "$skill_dir"
  done
}

link_kind "$CLAUDE_DEST" claude rules
link_kind "$CLAUDE_DEST" claude skills
link_kind "$(dirname "$COPILOT_SKILLS_DEST")" copilot skills
generate_copilot_instructions
generate_copilot_prompts skills
